ALTER TABLE competitions ADD COLUMN score_rules TEXT;
ALTER TABLE competitions ADD COLUMN rules_source_url TEXT NOT NULL DEFAULT '';
ALTER TABLE competitions ADD COLUMN rules_version TEXT NOT NULL DEFAULT 'เกณฑ์ตัวอย่างเดิม';
ALTER TABLE competitions ADD COLUMN min_students INTEGER NOT NULL DEFAULT 1;
INSERT INTO competitions(id,title,category,grade,cover,description,max_students,max_coaches,min_students,score_rules,rules_source_url,rules_version) VALUES('trial73-painting','วาดภาพระบายสี','ศิลปะ','ป.4–6','painting','เกณฑ์ปี 2568 ใช้ทดสอบเท่านั้น — หัวข้อปี 2568: จิตอาสา พาใจเป็นสุข ใช้สีไม้หรือสีชอล์ค กระดาษ 100 ปอนด์ 11 × 15 นิ้ว เวลา 3 ชั่วโมง จำนวนครูเป็นค่าทดสอบของผู้จัด โปรดอ่านข้อกำหนดฉบับเต็ม','1','1','1','[{"label": "ความสอดคล้องของภาพกับหัวข้อที่กำหนด", "max": 20}, {"label": "ความคิดสร้างสรรค์", "max": 20}, {"label": "เทคนิคการใช้สี", "max": 20}, {"label": "ความสวยงามและความสมบูรณ์ของภาพ", "max": 20}, {"label": "การจัดองค์ประกอบของภาพ", "max": 20}]','https://drive.google.com/file/d/1MZYpe-dzfKFfCZ42Qmcc3FRRl5OHEsOl/view#page=5','ครั้งที่ 73 ปีการศึกษา 2568 (ใช้ทดสอบ)');
INSERT INTO competitions(id,title,category,grade,cover,description,max_students,max_coaches,min_students,score_rules,rules_source_url,rules_version) VALUES('trial73-weaving','การแข่งขันจักสานไม้ไผ่','การงานอาชีพ','ป.4–6','weaving','เกณฑ์ปี 2568 ใช้ทดสอบเท่านั้น — ทีม 3 คน ครูผู้ฝึกสอน 2 คน เวลา 3 ชั่วโมง ทำแผ่นรองจาน 12 × 17 นิ้ว 2 แผ่น และแผ่นรองแก้ว 4 × 4 นิ้ว 4 แผ่น พร้อมแผ่นพับ A4 แสดงขั้นตอนและต้นทุน–กำไร รายละเอียดคะแนนย่อยตามต้นฉบับ','3','2','3','[{"label": "การเตรียมวัสดุอุปกรณ์", "max": 10}, {"label": "กระบวนการทำงาน", "max": 40}, {"label": "ผลงาน", "max": 50}]','https://drive.google.com/file/d/1SMOBlR_V6EnZcSFMA0waQRVVtqF0rMsq/view#page=4','ครั้งที่ 73 ปีการศึกษา 2568 (ใช้ทดสอบ)');
INSERT INTO competitions(id,title,category,grade,cover,description,max_students,max_coaches,min_students,score_rules,rules_source_url,rules_version) VALUES('trial73-singing','การแข่งขันขับร้องเพลงไทย','ศิลปะ','ป.1–6','singing','เกณฑ์ปี 2568 ใช้ทดสอบเท่านั้น — ประเภทเดี่ยว เพลงปี 2568: ขอมกล่อมลูก สองชั้น ใช้ทดสอบเท่านั้น เอกสารมีหมายเหตุเรื่องลำดับเพลงปี 2569 ผู้จัดต้องยืนยันเพลงก่อนแข่งขันจริง จำนวนครูเป็นค่าทดสอบของผู้จัด','1','1','1','[{"label": "ความแม่นยำและความถูกต้องของจังหวะและทำนองทางร้อง", "max": 30}, {"label": "ความไพเราะและคุณภาพของเสียงในการขับร้อง", "max": 30}, {"label": "เทคนิคการร้องและความสามารถของผู้ขับร้องเพลงไทย", "max": 20}, {"label": "ความเหมาะสมของแนวทางในการขับร้อง", "max": 10}, {"label": "บุคลิก ท่าทางในการขับร้อง", "max": 10}]','https://drive.google.com/file/d/127mWEL8u16zotZTKgTCEWbiWfIAku71U/view#page=7','ครั้งที่ 73 ปีการศึกษา 2568 (ใช้ทดสอบ)');
INSERT INTO competitions(id,title,category,grade,cover,description,max_students,max_coaches,min_students,score_rules,rules_source_url,rules_version) VALUES('trial73-comic','การสร้างการ์ตูนเรื่องสั้น (Comic Strip)','วิทยาศาสตร์และเทคโนโลยี','ป.4–6','computer','เกณฑ์ปี 2568 ใช้ทดสอบเท่านั้น — ทีม 2 คน เวลา 3 ชั่วโมง เล่าเรื่องต่อเนื่องกันแบบ 2 มิติ หัวข้อแจ้งในวันแข่งขัน สรุปแนวคิดไม่เกิน A4 1 หน้า จำนวนครูเป็นค่าทดสอบของผู้จัด รายละเอียดอุปกรณ์และข้อห้ามตามต้นฉบับ','2','2','2','[{"label": "ความถูกต้องสมบูรณ์ของผลงาน", "max": 30}, {"label": "ความคิดสร้างสรรค์", "max": 25}, {"label": "การออกแบบลักษณะของผลงาน", "max": 25}, {"label": "ความสวยงาม", "max": 20}]','https://drive.google.com/file/d/1TJNjVdUL8jYz_rVaNXsGUJ-jUBcMeI_6/view#page=5','ครั้งที่ 73 ปีการศึกษา 2568 (ใช้ทดสอบ)');
